CREATE TABLE character_attendance_eligibility (character_id TEXT PRIMARY KEY REFERENCES characters(id), start_at TEXT NOT NULL CHECK(length(start_at)=19 AND start_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]'), source TEXT NOT NULL CHECK(source IN ('attendance_capture','registry_request')));
--> statement-breakpoint
INSERT INTO character_attendance_eligibility(character_id,start_at,source) SELECT a.character_id,MIN(r.date||'T'||substr(t.source_time,12,8)),'attendance_capture' FROM attendance a JOIN ticks t ON t.id=a.tick_id JOIN raids r ON r.id=t.raid_id WHERE length(r.date)=10 AND length(t.source_time)>=19 GROUP BY a.character_id;
--> statement-breakpoint
INSERT INTO character_attendance_eligibility(character_id,start_at,source) SELECT q.character_id,MIN(substr(q.created_at,1,19)),'registry_request' FROM claims q WHERE length(q.created_at)>=19 AND substr(q.created_at,1,19) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]' GROUP BY q.character_id ON CONFLICT(character_id) DO UPDATE SET start_at=excluded.start_at,source=excluded.source WHERE excluded.start_at<character_attendance_eligibility.start_at;
--> statement-breakpoint
CREATE TRIGGER attendance_eligibility_from_capture AFTER INSERT ON attendance BEGIN INSERT INTO character_attendance_eligibility(character_id,start_at,source) SELECT NEW.character_id,r.date||'T'||substr(t.source_time,12,8),'attendance_capture' FROM ticks t JOIN raids r ON r.id=t.raid_id WHERE t.id=NEW.tick_id AND length(r.date)=10 AND length(t.source_time)>=19 ON CONFLICT(character_id) DO UPDATE SET start_at=excluded.start_at,source=excluded.source WHERE excluded.start_at<character_attendance_eligibility.start_at; END;
--> statement-breakpoint
CREATE TRIGGER attendance_eligibility_from_request AFTER INSERT ON claims WHEN length(NEW.created_at)>=19 AND substr(NEW.created_at,1,19) GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]' BEGIN INSERT INTO character_attendance_eligibility(character_id,start_at,source) VALUES(NEW.character_id,substr(NEW.created_at,1,19),'registry_request') ON CONFLICT(character_id) DO UPDATE SET start_at=excluded.start_at,source=excluded.source WHERE excluded.start_at<character_attendance_eligibility.start_at; END;
